import { describe, expect, it } from 'vitest'
import { cargoLockVersions, crateFor, tauriVersionMismatches } from './check-tauri-versions.mjs'

const CARGO_LOCK = [
    '# This file is automatically @generated by Cargo.',
    'version = 4',
    '',
    '[[package]]',
    'name = "tauri"',
    'version = "2.11.2"',
    'source = "registry+https://github.com/rust-lang/crates.io-index"',
    '',
    '[[package]]',
    'name = "tauri-plugin-fs"',
    'version = "2.5.1"',
    '',
    '[[package]]',
    'name = "windows-sys"',
    'version = "0.59.0"',
    '',
    '[[package]]',
    'name = "windows-sys"',
    'version = "0.61.2"',
    '',
].join('\r\n')

describe('cargoLockVersions', () => {
    it('reads every package and keeps each version of a crate', () => {
        const versions = cargoLockVersions(CARGO_LOCK)

        expect(versions.get('tauri')).toEqual(['2.11.2'])
        expect(versions.get('tauri-plugin-fs')).toEqual(['2.5.1'])
        expect(versions.get('windows-sys')).toEqual(['0.59.0', '0.61.2'])
    })
})

describe('tauriVersionMismatches', () => {
    const crates = cargoLockVersions(CARGO_LOCK)

    it('accepts packages on the same minor as their crates, whatever the patch', () => {
        const npm = new Map([
            ['@tauri-apps/api', '2.11.0'],
            ['@tauri-apps/plugin-fs', '2.5.3'],
            ['@tauri-apps/cli', '2.12.0'],
        ])

        expect(tauriVersionMismatches(npm, crates)).toEqual([])
    })

    it('reports a package a minor ahead of its crate, as the Tauri CLI would', () => {
        const npm = new Map([
            ['@tauri-apps/api', '2.12.0'],
            ['@tauri-apps/plugin-fs', '2.5.1'],
        ])

        expect(tauriVersionMismatches(npm, crates)).toEqual(["@tauri-apps/api 2.12.0 doesn't match tauri 2.11.2"])
    })

    it('reports a plugin package whose crate is missing', () => {
        expect(tauriVersionMismatches(new Map([['@tauri-apps/plugin-store', '2.4.3']]), crates)).toEqual([
            '@tauri-apps/plugin-store 2.4.3 has no tauri-plugin-store crate in src-tauri/Cargo.lock',
        ])
    })

    it('pairs the api package with tauri and each plugin with its crate', () => {
        expect(crateFor('@tauri-apps/api')).toBe('tauri')
        expect(crateFor('@tauri-apps/plugin-dialog')).toBe('tauri-plugin-dialog')
        expect(crateFor('@tauri-apps/cli')).toBeNull()
    })
})
